function RefBinder() {
	this._unboundIndex = -1;
}

/**
 * Invoke or update a ref using the committed vnode shape, tree pointers, and error hooks.
 * @param {{ ref: Ref<any>, value: any }} refBinding
 * @param {{ ref?: any, type?: any, component?: any, dom?: any }} vnodeShape
 * @param {{ parent?: any, children?: any, flags?: number, index?: number }} vnodeTree
 * @param {{ catchError?: Function }} optionsLease
 * @param {{ vnode?: VNode }} vnodeOwner
 */
RefBinder.prototype.applyRef = function (
	refBinding,
	vnodeShape,
	vnodeTree,
	optionsLease,
	vnodeOwner
) {
	try {
		let ref = refBinding.ref;
		let value = refBinding.value;
		let instance = value;
		let vnodeRef = vnodeShape.ref;
		let vnodeType = vnodeShape.type;
		let vnodeComponent = vnodeShape.component;
		let vnodeDom = vnodeShape.dom;
		let vnodeParent = vnodeTree.parent;
		let vnodeChildren = vnodeTree.children;
		let vnodeFlags = vnodeTree.flags;
		let vnodeIndex = vnodeTree.index;
		let inTree =
			vnodeParent !== undefined &&
			vnodeChildren !== undefined &&
			vnodeFlags !== undefined;
		let treeId = vnodeIndex;

		if (
			value != null &&
			vnodeRef == ref &&
			treeId != null &&
			treeId != this._unboundIndex &&
			inTree
		) {
			if (typeof vnodeType == 'function') {
				instance = vnodeComponent || value;
			} else {
				instance = vnodeDom || value;
			}
		}

		if (typeof ref == 'function') ref(instance);
		else ref.current = instance;
	} catch (e) {
		optionsLease.catchError(e, vnodeOwner.vnode);
	}
};

const refBinder = new RefBinder();

/**
 * Invoke or update a ref, depending on whether it is a function or object ref.
 * @param {Ref<any>} ref
 * @param {any} value
 * @param {VNode} vnode
 */
export function applyRef(ref, value, vnode) {
	refBinder.applyRef(
		new Fragment.RefBinding(ref, value),
		new Fragment.VNodeShape(vnode),
		new Fragment.VNodeTree(vnode),
		new BaseComponent.OptionsLease(options),
		new BaseComponent.VNodeOwner(vnode)
	);
}

